import { injectable } from 'inversify';
import { CmsService } from '@core/service';
import { ICmsRegisterStaticDataRepository } from '@src/domain/interfaces/cms/loan_register/registerStaticData';
import { CmsRegisterStaticData } from '@src/domain/entities/cms/loan_register/registerStaticData';

const getCmsRegisterStaticDataUrl = '/dl-loan-register-static-datas';
const defaultSegment = 'default';

@injectable()
export class CmsRegisterStaticDataRepository extends CmsService implements ICmsRegisterStaticDataRepository {
    constructor() {
        super();
    }

    async getCmsRegisterStaticData(segment: string): Promise<CmsRegisterStaticData | null> {
        try {
            const response = await this.get<CmsRegisterStaticData>(getCmsRegisterStaticDataUrl, {
                params: {
                    'populate': '*',
                },
            });

            return response.data as CmsRegisterStaticData ?? null;
        } catch (error) {
            throw error;
        }
    }
}
