import { injectable } from 'inversify';
import { CmsService } from '@core/service';
import { ICmsLoanRegisterConfigRepository } from '@src/domain/interfaces/cms/loan_register/loanRegisterConfig';
import { CmsLoanRegisterConfig } from '@src/domain/entities/cms/loan_register/loanRegisterConfig';

const getCmsLoanRegisterConfigUrl = '/dl-loan-register-config';
const defaultSegment = 'default';

@injectable()
export class CmsLoanRegisterConfigRepository extends CmsService implements ICmsLoanRegisterConfigRepository {
    constructor() {
        super();
    }
    async getCmsLoanRegisterConfig(segment: string): Promise<CmsLoanRegisterConfig | null> {
        try {
            const response = await this.get<CmsLoanRegisterConfig>(getCmsLoanRegisterConfigUrl, {
                params: {
                    'populate': '*',
                },
            });
            return response.data as CmsLoanRegisterConfig ?? null;
        } catch (error) {
            throw error;
        }

    }
}
